import Events from "./events.js";
import { serveFile } from "./utils/serve-file.js";
import { cwd } from "./services/process.js";
import { merge } from "./utils/object.js";
import { serve } from "./services/net.js";
export const defaults = {
    root: `${cwd()}/_site`,
    port: 8000,
    serveFile,
};
export default class Server {
    events = new Events();
    options;
    middlewares = [];
    fetch;
    #server;
    #waiting = false;
    constructor(options) {
        this.options = merge(defaults, options);
        if (this.options.hostname === "localhost") {
            this.options.hostname = "0.0.0.0";
        }
        // Create the fetch function for `deno serve`
        this.fetch = (request, info) => {
            return this.handle(request, info);
        };
    }
    /** The local address this server is listening on. */
    get addr() {
        return this.#server?.addr;
    }
    /** The port this server is listening on */
    get port() {
        return this.options.port;
    }
    /** The hostname this server is listening on */
    get hostname() {
        const { hostname } = this.options;
        return hostname === "0.0.0.0" || hostname === "127.0.0.1"
            ? "localhost"
            : (hostname ?? "localhost");
    }
    /** Register one or more middlewares */
    use(...middleware) {
        this.middlewares.push(...middleware);
        return this;
    }
    /** Register one or more middlewares at the beginning of the list */
    useFirst(...middleware) {
        this.middlewares.unshift(...middleware);
        return this;
    }
    /** Add a listener to an event */
    addEventListener(type, listener, options) {
        this.events.addEventListener(type, listener, options);
        return this;
    }
    /** Dispatch an event */
    dispatchEvent(event) {
        return this.events.dispatchEvent(event);
    }
    /** Start the server in waiting mode */
    wait() {
        this.#waiting = true;
        this.start();
    }
    /** Start the server */
    start(signal) {
        if (!this.#server) {
            this.#server = serve({
                ...this.options,
                handler: this.handle.bind(this),
                signal,
                onListen: () => {
                    if (!this.#waiting) {
                        void this.dispatchEvent({ type: "start" });
                    }
                },
                onUpgradeWebSocket: (socket) => {
                    void this.dispatchEvent({ type: "upgrade", socket });
                },
            });
        }
        else if (this.#waiting) {
            this.#waiting = false;
            void this.dispatchEvent({ type: "start" });
        }
    }
    /** Stops the server */
    stop() {
        try {
            this.#server?.shutdown();
        }
        catch (err) {
            void this.dispatchEvent({
                type: "error",
                error: err,
            });
        }
    }
    /** Handle a http request event */
    async handle(request, info) {
        if (this.#waiting) {
            return this.handleWait();
        }
        const middlewares = [...this.middlewares];
        const next = async (request) => {
            const middleware = middlewares.shift();
            if (middleware) {
                return await middleware(request, next, info);
            }
            return await this.options.serveFile(this.options.root, request);
        };
        return await next(request);
    }
    handleWait(url) {
        return new Response(`<html>
      <head>
        <meta charset="utf-8">
        <title>Por favor, agarde - Please wait</title>
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <style>
        body {
          font-family: system-ui, sans-serif;
          margin: 0;
          padding: 2rem;
          box-sizing: border-box;
          display: grid;
          grid-template-columns: minmax(0, 800px);
          align-content: center;
          justify-content: center;
          min-height: 100vh
        }
        </style>
      </head>
      <body>
      <pre><samp>Por favor, agarde - Please wait\n</samp></pre>
      <script type="module">
        const samp = document.querySelector("samp");
        const timeout = 1000;
        while (true) {
          try {
            const url = ${url ? `"${url}"` : "document.location"};
            const response = await fetch(url);
            if (response.headers.get("X-Lume-CMS") !== "wait") {
              document.location = url;
              break;
            }
          } catch {}

          samp.textContent += ".";
          await new Promise((resolve) => setTimeout(resolve, timeout));
        }
      </script>
      </body>
      </html>`, {
            status: 200,
            headers: {
                "Content-Type": "text/html",
                "X-Lume-CMS": "wait",
            },
        });
    }
}
